    static func image(_ svg: String) -> NSImage {
        NSImage(data: Data(svg.utf8)) ?? NSImage()
    }

    static let mark = image(markSVG)
    static let logoLight = image(logoSVG)
    /// No escuro, o nome passa de #1C2025 para um cinza claro (o resto do desenho é igual).
    static let logoDark = image(logoSVG.replacingOccurrences(of: "#1C2025", with: "#ECEDEE"))
}

/// Logo completo (marca + nome), trocando de cor no tema escuro.
struct BrandLogo: View {
    var height: CGFloat = 24
    @Environment(\.colorScheme) private var scheme

    var body: some View {
        Image(nsImage: scheme == .dark ? Brand.logoDark : Brand.logoLight)
            .resizable()
            .interpolation(.high)
            .scaledToFit()
            .frame(height: height)
            .accessibilityLabel(Brand.name)
    }
}

/// Ícone do app desenhado a partir da marca: fundo branco arredondado, marca verde no centro.
struct AppIconArt: View {
    var body: some View {
        ZStack {
            RoundedRectangle(cornerRadius: 185, style: .continuous)
                .fill(Color(white: 0.995))
                .shadow(color: .black.opacity(0.18), radius: 18, y: 10)
            Image(nsImage: Brand.mark)
                .resizable()
                .interpolation(.high)
                .scaledToFit()
                .padding(110)
        }
        .frame(width: 824, height: 824)
        .padding(100)
        .frame(width: 1024, height: 1024)
    }
}
